package com.lockboxcaseopening;

/**
 * What a mouse press does while the animation is showing.
 */
public enum ClickAction
{
	CONSUME,
	CLOSE_AND_PASS,
	CLOSE_AND_CONSUME
}

package com.lockboxcaseopening;

import java.util.Random;
import net.runelite.api.gameval.ItemID;

/**
 * The Forgotten lockbox drop table, from the OSRS Wiki. Weights are out of 403.
 * An item's tier comes from its combined chance across all of its quantities.
 */
public final class DropTable
{
	public static final int LOCKBOX_ID = ItemID.FORGOTTEN_LOCKBOX;

	private static final class Entry
	{
		private final Loot loot;
		private final int weight;

		private Entry(int itemId, int quantity, int weight, Tier tier)
		{
			this.loot = new Loot(itemId, quantity, tier);
			this.weight = weight;
		}
	}

	private static final Entry[] ENTRIES = {
		new Entry(ItemID.OATHPLATE_SHARDS, 14, 60, Tier.COMMON),
		new Entry(ItemID.OATHPLATE_SHARDS, 11, 50, Tier.COMMON),
		new Entry(ItemID.DRAGON_DART, 125, 60, Tier.COMMON),
		new Entry(ItemID.DRAGON_DART, 80, 50, Tier.COMMON),
		new Entry(ItemID.DRAGON_BOLTS_UNFEATHERED, 125, 60, Tier.UNCOMMON),
		new Entry(ItemID.DRAGON_PLATELEGS, 1, 50, Tier.RARE),
		new Entry(ItemID.DRAGON_PLATESKIRT, 1, 50, Tier.RARE),
		new Entry(ItemID.COINS, 233333, 20, Tier.VERY_RARE),
		new Entry(ItemID.OATHPLATE_HELM, 1, 1, Tier.LEGENDARY),
		new Entry(ItemID.OATHPLATE_CHEST, 1, 1, Tier.LEGENDARY),
		new Entry(ItemID.OATHPLATE_LEGS, 1, 1, Tier.LEGENDARY),
	};

	private DropTable()
	{
	}

	public static int totalWeight()
	{
		int total = 0;
		for (Entry entry : ENTRIES)
		{
			total += entry.weight;
		}
		return total;
	}

	/**
	 * Picks a reward using the real odds.
	 */
	public static Loot roll(Random random)
	{
		int remaining = random.nextInt(totalWeight());
		for (Entry entry : ENTRIES)
		{
			remaining -= entry.weight;
			if (remaining < 0)
			{
				return entry.loot;
			}
		}
		throw new IllegalStateException("roll fell outside the drop table");
	}

	/**
	 * Builds a reward for any item, using Tier.UNKNOWN if it isn't in the table.
	 */
	public static Loot of(int itemId, int quantity)
	{
		for (Entry entry : ENTRIES)
		{
			if (entry.loot.getItemId() == itemId)
			{
				return new Loot(itemId, quantity, entry.loot.getTier());
			}
		}
		return new Loot(itemId, quantity, Tier.UNKNOWN);
	}

	public static boolean isEntry(int itemId, int quantity)
	{
		for (Entry entry : ENTRIES)
		{
			if (entry.loot.getItemId() == itemId && entry.loot.getQuantity() == quantity)
			{
				return true;
			}
		}
		return false;
	}
}

package com.lockboxcaseopening;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws a solid panel over the inventory until the reel stops, so the loot
 * can't be seen early. It only reads widget positions and never changes them.
 */
@Singleton
public class InventoryCoverOverlay extends Overlay
{
	private static final String TEXT = "Unboxing…";
	private static final Color COVER_COLOR = new Color(0x1A1A1A);

	private final Client client;
	private final UnboxController controller;

	private volatile Rectangle bounds;

	@Inject
	public InventoryCoverOverlay(Client client, UnboxController controller)
	{
		this.client = client;
		this.controller = controller;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		// Below the panel, which can overlap the inventory in small windows.
		setPriority(Overlay.PRIORITY_HIGH);
	}

	/**
	 * The area covered, or null if nothing is. Safe to read from any thread.
	 */
	public Rectangle bounds()
	{
		return bounds;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!controller.coverVisible(System.nanoTime()))
		{
			bounds = null;
			return null;
		}

		Rectangle covered = union(widgetBounds(InterfaceID.Inventory.ITEMS), widgetBounds(InterfaceID.Bankside.ITEMS));
		bounds = covered;
		if (covered != null)
		{
			graphics.setColor(COVER_COLOR);
			graphics.fill(covered);
			UnboxOverlay.drawCentered(graphics, TEXT, (int) covered.getCenterX(), (int) covered.getCenterY(), Color.WHITE);
		}
		return null;
	}

	private Rectangle widgetBounds(int componentId)
	{
		Widget widget = client.getWidget(componentId);
		return widget == null || widget.isHidden() ? null : widget.getBounds();
	}

	private static Rectangle union(Rectangle first, Rectangle second)
	{
		if (first == null)
		{
			return second;
		}
		return second == null ? first : first.union(second);
	}
}

package com.lockboxcaseopening;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("lockboxcaseopening")
public interface LockboxCaseOpeningConfig extends Config
{
	@Range(min = 3, max = 10)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "spinSeconds",
		name = "Spin duration",
		description = "How long the reel spins before it stops",
		position = 1
	)
	default int spinSeconds()
	{
		return 6;
	}

	@Range(min = 1, max = 15)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "revealSeconds",
		name = "Reveal duration",
		description = "How long the result stays up. Oathplate stays until you click",
		position = 2
	)
	default int revealSeconds()
	{
		return 4;
	}

	@ConfigItem(
		keyName = "soundEffects",
		name = "Sound effects",
		description = "Play in-game UI sounds during the animation",
		position = 3
	)
	default boolean soundEffects()
	{
		return true;
	}
}

package com.lockboxcaseopening;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Lockbox Case Opening",
	description = "Plays a case opening reel when you open a Forgotten lockbox",
	tags = {"yama", "lockbox", "forgotten", "oathplate", "case opening", "reel", "unboxing", "animation"}
)
public class LockboxCaseOpeningPlugin extends Plugin
{
	private static final String OPEN_OPTION = "Open";

	private static final int[] RESULT_POPUPS = {
		InterfaceID.Objectbox.UNIVERSE,
		InterfaceID.ObjectboxDouble.UNIVERSE,
		InterfaceID.Messagebox.UNIVERSE,
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private LockboxCaseOpeningConfig config;

	@Inject
	private UnboxController controller;

	@Inject
	private UnboxOverlay unboxOverlay;

	@Inject
	private InventoryCoverOverlay coverOverlay;

	// Only touched on the client thread.
	private final List<Widget> hiddenPopups = new ArrayList<>();

	private UnboxMouseListener mouseListener;
	private volatile boolean mouseListenerRegistered;

	@Provides
	LockboxCaseOpeningConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LockboxCaseOpeningConfig.class);
	}

	/**
	 * True for states that mean the player left the world. Loading isn't one of
	 * them, because it also happens when walking between map regions.
	 */
	static boolean endsSession(GameState state)
	{
		return state != GameState.LOGGED_IN && state != GameState.LOADING;
	}

	@Override
	protected void startUp()
	{
		mouseListener = new UnboxMouseListener(controller, unboxOverlay::bounds, coverOverlay::bounds, clientThread::invoke);
		overlayManager.add(unboxOverlay);
		overlayManager.add(coverOverlay);
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(() ->
		{
			controller.close();
			restorePopups();
		});
		unregisterMouseListener();
		overlayManager.remove(unboxOverlay);
		overlayManager.remove(coverOverlay);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.isConsumed() || !event.isItemOp() || event.getItemId() != DropTable.LOCKBOX_ID
			|| !OPEN_OPTION.equals(event.getMenuOption()))
		{
			return;
		}
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return;
		}
		controller.openClicked(itemCounts(inventory), System.nanoTime(), config.spinSeconds(), config.revealSeconds());
		registerMouseListener();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			controller.inventoryChanged(itemCounts(event.getItemContainer()), System.nanoTime());
		}
	}

	/**
	 * Hides the game's own result popup in the chatbox while the reel runs, so
	 * it can't show the loot early, and brings it back once the reel is gone.
	 */
	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (controller.isActive())
		{
			hidePopups();
		}
		else
		{
			restorePopups();
		}
	}

	private void hidePopups()
	{
		for (int component : RESULT_POPUPS)
		{
			Widget widget = client.getWidget(component);
			if (widget != null && !widget.isHidden())
			{
				widget.setHidden(true);
				hiddenPopups.add(widget);
			}
		}
	}

	/**
	 * Shows only the popups this plugin hid, never one the game hid itself.
	 */
	private void restorePopups()
	{
		for (Widget widget : hiddenPopups)
		{
			widget.setHidden(false);
		}
		hiddenPopups.clear();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		controller.gameTick();
		if (!controller.isActive() && !mouseListener.awaitingRelease())
		{
			unregisterMouseListener();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Hitsplat hitsplat = event.getHitsplat();
		if (event.getActor() == client.getLocalPlayer() && hitsplat.getAmount() > 0
			&& hitsplat.getHitsplatType() != HitsplatID.HEAL)
		{
			controller.close();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (endsSession(event.getGameState()))
		{
			controller.close();
			unregisterMouseListener();
		}
	}

	private static Map<Integer, Integer> itemCounts(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				counts.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return counts;
	}

	private void registerMouseListener()
	{
		if (!mouseListenerRegistered && controller.isActive())
		{
			UnboxMouseListener.register(mouseManager, mouseListener);
			mouseListenerRegistered = true;
		}
	}

	private void unregisterMouseListener()
	{
		if (mouseListenerRegistered)
		{
			mouseManager.unregisterMouseListener(mouseListener);
			mouseListenerRegistered = false;
		}
	}
}

package com.lockboxcaseopening;

import lombok.Value;

/**
 * One reward: an item, how many of it, and its rarity tier.
 */
@Value
public class Loot
{
	int itemId;
	int quantity;
	Tier tier;
}

package com.lockboxcaseopening;

import java.util.Map;
import java.util.Optional;

/**
 * Works out what a lockbox gave by comparing the inventory before and after.
 * Maps are item ID to total quantity.
 */
public final class LootDiff
{
	private LootDiff()
	{
	}

	public static int boxesConsumed(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		return Math.max(0, count(before, DropTable.LOCKBOX_ID) - count(after, DropTable.LOCKBOX_ID));
	}

	/**
	 * Prefers a gain matching a drop table entry, so an unrelated change on the
	 * same tick can't be mistaken for the loot. Otherwise uses the largest gain.
	 */
	public static Optional<Loot> gained(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		Loot largest = null;
		for (Map.Entry<Integer, Integer> item : after.entrySet())
		{
			int itemId = item.getKey();
			int gain = item.getValue() - count(before, itemId);
			if (itemId == DropTable.LOCKBOX_ID || gain <= 0)
			{
				continue;
			}
			if (DropTable.isEntry(itemId, gain))
			{
				return Optional.of(DropTable.of(itemId, gain));
			}
			if (largest == null || gain > largest.getQuantity())
			{
				largest = DropTable.of(itemId, gain);
			}
		}
		return Optional.ofNullable(largest);
	}

	private static int count(Map<Integer, Integer> items, int itemId)
	{
		return items.getOrDefault(itemId, 0);
	}
}

package com.lockboxcaseopening;

import java.util.HashMap;
import java.util.Map;
import java.util.Random;

/**
 * The motion of one reel. The reel spins at a constant speed until the result
 * is known, then eases to a stop on the winning tile. All times are supplied in
 * nanoseconds, so it runs independently of game ticks.
 */
public class ReelAnimation
{
	public enum Phase
	{
		SPINNING,
		SETTLING,
		REVEAL,
		DONE
	}

	public static final double SPIN_TILES_PER_SECOND = 24.0;
	public static final double MIN_SETTLE_SECONDS = 2.0;
	public static final int VISIBLE_HALF_TILES = 4;
	public static final double MAX_LAND_OFFSET = 0.35;

	private static final double NANOS_PER_SECOND = 1_000_000_000.0;

	private final Random random;
	private final long startNanos;
	private final int spinSeconds;
	private final int revealSeconds;
	private final Map<Integer, Loot> tiles = new HashMap<>();

	// Written last in setWinner, so other threads reading it see the fields below.
	private volatile Loot winner;
	private int winnerIndex;
	private long settleStartNanos;
	private double settleStartPosition;
	private double settleDistance;
	private double settleSeconds;

	public ReelAnimation(Random random, long startNanos, int spinSeconds, int revealSeconds)
	{
		this.random = random;
		this.startNanos = startNanos;
		this.spinSeconds = spinSeconds;
		this.revealSeconds = revealSeconds;
	}

	/**
	 * Places the winner on a tile still out of view and starts easing towards it.
	 * Ease-out cubic starts at speed 3D/T, so T is derived from the distance to
	 * keep the speed continuous. That shifts the stop by a fraction of a second.
	 */
	public void setWinner(Loot winner, long nowNanos)
	{
		double elapsed = seconds(nowNanos - startNanos);
		double wantedSeconds = Math.max(spinSeconds - elapsed, MIN_SETTLE_SECONDS);
		double speed = SPIN_TILES_PER_SECOND;

		settleStartPosition = speed * elapsed;
		settleStartNanos = nowNanos;
		winnerIndex = (int) Math.ceil(settleStartPosition + speed * wantedSeconds / 3);

		double offset = (random.nextDouble() * 2 - 1) * MAX_LAND_OFFSET;
		settleDistance = winnerIndex + offset - settleStartPosition;
		settleSeconds = 3 * settleDistance / speed;

		tiles.put(winnerIndex, winner);
		this.winner = winner;
	}

	/**
	 * Reel position in tiles. Tile i sits under the marker at position i.
	 */
	public double position(long nowNanos)
	{
		if (winner == null)
		{
			return SPIN_TILES_PER_SECOND * seconds(nowNanos - startNanos);
		}
		double progress = Math.min(1, Math.max(0, seconds(nowNanos - settleStartNanos) / settleSeconds));
		return settleStartPosition + settleDistance * (1 - Math.pow(1 - progress, 3));
	}

	public Loot tile(int index)
	{
		return tiles.computeIfAbsent(index, i -> DropTable.roll(random));
	}

	public Phase phase(long nowNanos)
	{
		if (winner == null)
		{
			return Phase.SPINNING;
		}
		double sinceStop = secondsSinceStop(nowNanos);
		if (sinceStop < 0)
		{
			return Phase.SETTLING;
		}
		if (winner.getTier() != Tier.LEGENDARY && sinceStop >= revealSeconds)
		{
			return Phase.DONE;
		}
		return Phase.REVEAL;
	}

	public boolean coverVisible(long nowNanos)
	{
		Phase phase = phase(nowNanos);
		return phase == Phase.SPINNING || phase == Phase.SETTLING;
	}

	/**
	 * Seconds since the reel stopped. Only meaningful once a winner is set.
	 */
	public double secondsSinceStop(long nowNanos)
	{
		return seconds(nowNanos - settleStartNanos) - settleSeconds;
	}

	public boolean hasWinner()
	{
		return winner != null;
	}

	public Loot winner()
	{
		return winner;
	}

	public int winnerIndex()
	{
		return winnerIndex;
	}

	private static double seconds(long nanos)
	{
		return nanos / NANOS_PER_SECOND;
	}
}

package com.lockboxcaseopening;

import java.awt.Color;

/**
 * Rarity tier of a lockbox reward, ordered from most to least likely.
 */
public enum Tier
{
	COMMON("Common", new Color(0x4B69FF)),
	UNCOMMON("Uncommon", new Color(0x8847FF)),
	RARE("Rare", new Color(0xD32CE6)),
	VERY_RARE("Very rare", new Color(0xEB4B4B)),
	LEGENDARY("Legendary", new Color(0xFFD700)),
	UNKNOWN("Unknown", new Color(0x9E9E9E));

	private final String label;
	private final Color color;

	Tier(String label, Color color)
	{
		this.label = label;
		this.color = color;
	}

	public String label()
	{
		return label;
	}

	public Color color()
	{
		return color;
	}
}

package com.lockboxcaseopening;

import java.util.Map;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Runs one unboxing from start to finish: waits for the real result, passes it
 * to the reel, and ends the animation. Call everything except the getters on
 * the client thread.
 */
@Singleton
public class UnboxController
{
	public static final int TIMEOUT_TICKS = 5;

	private final Random random;

	private volatile ReelAnimation animation;
	private Map<Integer, Integer> before;
	private int ticksWaited;

	@Inject
	public UnboxController()
	{
		this(new Random());
	}

	UnboxController(Random random)
	{
		this.random = random;
	}

	/**
	 * Starts an unboxing. A spin in progress is left alone, but a reveal gives
	 * way to it.
	 */
	public void openClicked(Map<Integer, Integer> before, long nowNanos, int spinSeconds, int revealSeconds)
	{
		ReelAnimation current = animation;
		if (current != null && current.coverVisible(nowNanos))
		{
			return;
		}
		this.before = before;
		ticksWaited = 0;
		animation = new ReelAnimation(random, nowNanos, spinSeconds, revealSeconds);
	}

	public void inventoryChanged(Map<Integer, Integer> after, long nowNanos)
	{
		ReelAnimation current = animation;
		if (current == null || current.hasWinner())
		{
			return;
		}
		int consumed = LootDiff.boxesConsumed(before, after);
		if (consumed == 0)
		{
			// Keeps anything gained while waiting from being counted as loot.
			before = after;
			return;
		}
		Loot loot = LootDiff.gained(before, after).orElse(null);
		if (consumed > 1 || loot == null)
		{
			// Two results can't be told apart, and the reel must never guess.
			close();
			return;
		}
		current.setWinner(loot, nowNanos);
	}

	public void gameTick()
	{
		ReelAnimation current = animation;
		if (current == null || current.hasWinner())
		{
			return;
		}
		ticksWaited++;
		if (ticksWaited >= TIMEOUT_TICKS)
		{
			close();
		}
	}

	public void update(long nowNanos)
	{
		ReelAnimation current = animation;
		if (current != null && current.phase(nowNanos) == ReelAnimation.Phase.DONE)
		{
			close();
		}
	}

	public void close()
	{
		animation = null;
		before = null;
	}

	/**
	 * Closes only if the given animation is still the current one, so a close
	 * queued by an old click can't end a newer animation.
	 */
	public void close(ReelAnimation expected)
	{
		if (animation == expected)
		{
			close();
		}
	}

	public ReelAnimation animation()
	{
		return animation;
	}

	/**
	 * True while the inventory should be covered. Safe to call from any thread.
	 */
	public boolean coverVisible(long nowNanos)
	{
		ReelAnimation current = animation;
		return current != null && current.coverVisible(nowNanos);
	}

	public boolean isActive()
	{
		return animation != null;
	}
}

package com.lockboxcaseopening;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;

/**
 * Closes the animation on a click outside the panel. Only registered while an
 * animation is showing. Mouse callbacks run off the client thread, so closing is
 * handed over through the supplied executor.
 */
public class UnboxMouseListener extends MouseAdapter
{
	private final UnboxController controller;
	private final Supplier<Rectangle> panel;
	private final Supplier<Rectangle> cover;
	private final Consumer<Runnable> clientThread;

	private volatile boolean swallowRelease;
	private volatile boolean swallowClick;

	public UnboxMouseListener(UnboxController controller, Supplier<Rectangle> panel, Supplier<Rectangle> cover,
		Consumer<Runnable> clientThread)
	{
		this.controller = controller;
		this.panel = panel;
		this.cover = cover;
		this.clientThread = clientThread;
	}

	/**
	 * Adds the listener at the end of the list, after stretched mode's listener
	 * has translated the click into the coordinates the overlays draw in.
	 */
	static void register(MouseManager mouseManager, UnboxMouseListener listener)
	{
		mouseManager.registerMouseListener(listener);
	}

	static ClickAction decide(Point point, Rectangle panel, Rectangle cover, ReelAnimation.Phase phase)
	{
		if (panel != null && panel.contains(point))
		{
			boolean spinning = phase == ReelAnimation.Phase.SPINNING || phase == ReelAnimation.Phase.SETTLING;
			return spinning ? ClickAction.CONSUME : ClickAction.CLOSE_AND_CONSUME;
		}
		if (cover != null && cover.contains(point))
		{
			return ClickAction.CLOSE_AND_CONSUME;
		}
		return ClickAction.CLOSE_AND_PASS;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		swallowRelease = false;
		swallowClick = false;

		ReelAnimation reel = controller.animation();
		if (reel == null)
		{
			return event;
		}

		ClickAction action = decide(event.getPoint(), panel.get(), cover.get(), reel.phase(System.nanoTime()));
		if (action != ClickAction.CONSUME)
		{
			clientThread.accept(() -> controller.close(reel));
		}
		if (action != ClickAction.CLOSE_AND_PASS)
		{
			swallowRelease = true;
			swallowClick = true;
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event)
	{
		if (swallowRelease)
		{
			swallowRelease = false;
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event)
	{
		if (swallowClick)
		{
			swallowClick = false;
			event.consume();
		}
		return event;
	}

	/**
	 * True between a consumed press and its release. The listener has to stay
	 * registered until then, or the game would see half a click.
	 */
	public boolean awaitingRelease()
	{
		return swallowRelease;
	}
}

package com.lockboxcaseopening;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.SoundEffectID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.QuantityFormatter;

/**
 * Draws the centred panel, the reel and the result.
 */
@Singleton
public class UnboxOverlay extends Overlay
{
	private static final String TITLE = "FORGOTTEN LOCKBOX";
	private static final int MAX_WIDTH = 720;
	private static final int MAX_HEIGHT = 190;
	private static final int MARGIN = 20;
	private static final int TILE_WIDTH = 104;
	private static final int TILE_PITCH = TILE_WIDTH + 8;
	private static final int FADE_WIDTH = 70;
	private static final int HEADER_HEIGHT = 34;
	private static final int FOOTER_HEIGHT = 40;
	private static final int MIN_REEL_HEIGHT = 40;
	private static final long TICK_SOUND_GAP_NANOS = 60_000_000L;
	private static final double GOLD_FLASH_SECONDS = 0.6;

	private static final Color PANEL_COLOR = new Color(0x16171B);
	private static final Color PANEL_EDGE = new Color(0x3A3C44);
	private static final Color TILE_COLOR = new Color(0x26282E);
	private static final Color MARKER_COLOR = new Color(0xFFD700);

	private final Client client;
	private final ItemManager itemManager;
	private final UnboxController controller;
	private final LockboxCaseOpeningConfig config;

	private volatile Rectangle bounds;
	private ReelAnimation soundAnimation;
	private long lastTile;
	private long lastTickSoundNanos;
	private boolean stopSoundPlayed;

	@Inject
	public UnboxOverlay(Client client, ItemManager itemManager, UnboxController controller, LockboxCaseOpeningConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.controller = controller;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(Overlay.PRIORITY_HIGHEST);
	}

	static Rectangle panelBounds(int canvasWidth, int canvasHeight)
	{
		int width = Math.min(MAX_WIDTH, canvasWidth - MARGIN * 2);
		int height = Math.min(MAX_HEIGHT, canvasHeight - MARGIN * 2);
		return new Rectangle((canvasWidth - width) / 2, (canvasHeight - height) / 2, width, height);
	}

	/**
	 * The panel as last drawn, or null when idle. Safe to read from any thread.
	 */
	public Rectangle bounds()
	{
		return bounds;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		long now = System.nanoTime();
		controller.update(now);
		ReelAnimation reel = controller.animation();
		if (reel == null)
		{
			bounds = null;
			soundAnimation = null;
			return null;
		}

		Rectangle panel = panelBounds(client.getCanvasWidth(), client.getCanvasHeight());
		bounds = panel;
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

		ReelAnimation.Phase phase = reel.phase(now);
		double position = reel.position(now);

		drawPanel(graphics, panel);
		drawHeader(graphics, panel);
		drawReel(graphics, panel, reel, position, phase, now);
		if (phase == ReelAnimation.Phase.REVEAL)
		{
			drawResult(graphics, panel, reel.winner());
			drawGoldFlash(graphics, panel, reel, now);
		}
		playSounds(reel, position, phase, now);
		return null;
	}

	private void drawPanel(Graphics2D graphics, Rectangle panel)
	{
		graphics.setColor(PANEL_COLOR);
		graphics.fillRoundRect(panel.x, panel.y, panel.width, panel.height, 12, 12);
		graphics.setColor(PANEL_EDGE);
		graphics.drawRoundRect(panel.x, panel.y, panel.width, panel.height, 12, 12);
	}

	private static void drawHeader(Graphics2D graphics, Rectangle panel)
	{
		drawCentered(graphics, TITLE, panel.x + panel.width / 2, panel.y + 22, Color.WHITE);
	}

	private void drawReel(Graphics2D graphics, Rectangle panel, ReelAnimation reel, double position,
		ReelAnimation.Phase phase, long now)
	{
		int reelHeight = Math.max(MIN_REEL_HEIGHT, panel.height - HEADER_HEIGHT - FOOTER_HEIGHT);
		Rectangle area = new Rectangle(panel.x + 8, panel.y + HEADER_HEIGHT, panel.width - 16, reelHeight);
		int centre = panel.x + panel.width / 2;

		Shape oldClip = graphics.getClip();
		graphics.clip(area);

		int nearest = (int) Math.round(position);
		for (int i = nearest - ReelAnimation.VISIBLE_HALF_TILES; i <= nearest + ReelAnimation.VISIBLE_HALF_TILES; i++)
		{
			int x = (int) Math.round(centre + (i - position) * TILE_PITCH - TILE_WIDTH / 2.0);
			boolean won = phase == ReelAnimation.Phase.REVEAL && i == reel.winnerIndex();
			drawTile(graphics, new Rectangle(x, area.y, TILE_WIDTH, area.height), reel.tile(i), won);
		}

		Color clear = new Color(PANEL_COLOR.getRed(), PANEL_COLOR.getGreen(), PANEL_COLOR.getBlue(), 0);
		graphics.setPaint(new GradientPaint(area.x, 0, PANEL_COLOR, area.x + FADE_WIDTH, 0, clear));
		graphics.fillRect(area.x, area.y, FADE_WIDTH, area.height);
		int right = area.x + area.width;
		graphics.setPaint(new GradientPaint(right - FADE_WIDTH, 0, clear, right, 0, PANEL_COLOR));
		graphics.fillRect(right - FADE_WIDTH, area.y, FADE_WIDTH, area.height);

		graphics.setClip(oldClip);

		graphics.setColor(MARKER_COLOR);
		graphics.fillRect(centre - 1, area.y - 3, 2, area.height + 6);
	}

	private void drawTile(Graphics2D graphics, Rectangle tile, Loot loot, boolean won)
	{
		Color color = loot.getTier().color();
		graphics.setColor(TILE_COLOR);
		graphics.fillRect(tile.x, tile.y, tile.width, tile.height);

		Color glow = new Color(color.getRed(), color.getGreen(), color.getBlue(), won ? 130 : 70);
		Color clear = new Color(color.getRed(), color.getGreen(), color.getBlue(), 0);
		graphics.setPaint(new GradientPaint(0, tile.y, clear, 0, tile.y + tile.height, glow));
		graphics.fillRect(tile.x, tile.y, tile.width, tile.height);

		graphics.setColor(color);
		graphics.fillRect(tile.x, tile.y + tile.height - 5, tile.width, 5);

		if (loot.getTier() == Tier.LEGENDARY && !won)
		{
			drawStar(graphics, tile, color);
		}
		else
		{
			drawItem(graphics, tile, loot);
		}

		if (won)
		{
			graphics.setColor(color);
			graphics.setStroke(new BasicStroke(2));
			graphics.drawRect(tile.x + 1, tile.y + 1, tile.width - 2, tile.height - 2);
		}
	}

	private void drawItem(Graphics2D graphics, Rectangle tile, Loot loot)
	{
		BufferedImage image = itemManager.getImage(loot.getItemId(), loot.getQuantity(), loot.getQuantity() > 1);
		int scale = tile.height >= 80 ? 2 : 1;
		int width = image.getWidth() * scale;
		int height = image.getHeight() * scale;
		int x = tile.x + (tile.width - width) / 2;
		int y = tile.y + (tile.height - height) / 2;
		graphics.drawImage(image, x, y, width, height, null);
	}

	private static void drawStar(Graphics2D graphics, Rectangle tile, Color color)
	{
		double centreX = tile.getCenterX();
		double centreY = tile.getCenterY();
		double outer = Math.min(tile.width, tile.height) * 0.3;
		double inner = outer * 0.42;

		Path2D star = new Path2D.Double();
		for (int i = 0; i < 10; i++)
		{
			double radius = i % 2 == 0 ? outer : inner;
			double angle = -Math.PI / 2 + i * Math.PI / 5;
			double x = centreX + radius * Math.cos(angle);
			double y = centreY + radius * Math.sin(angle);
			if (i == 0)
			{
				star.moveTo(x, y);
			}
			else
			{
				star.lineTo(x, y);
			}
		}
		star.closePath();
		graphics.setColor(color);
		graphics.fill(star);
	}

	private void drawResult(Graphics2D graphics, Rectangle panel, Loot loot)
	{
		String name = itemManager.getItemComposition(loot.getItemId()).getName();
		String quantity = loot.getQuantity() > 1 ? " x " + QuantityFormatter.formatNumber(loot.getQuantity()) : "";
		String text = name + quantity + " · " + loot.getTier().label();
		drawCentered(graphics, text, panel.x + panel.width / 2, panel.y + panel.height - 14, loot.getTier().color());
	}

	private static void drawGoldFlash(Graphics2D graphics, Rectangle panel, ReelAnimation reel, long now)
	{
		double since = reel.secondsSinceStop(now);
		if (reel.winner().getTier() != Tier.LEGENDARY || since >= GOLD_FLASH_SECONDS)
		{
			return;
		}
		float strength = (float) (0.5 * (1 - since / GOLD_FLASH_SECONDS));
		Composite old = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, strength));
		graphics.setColor(Tier.LEGENDARY.color());
		graphics.fillRoundRect(panel.x, panel.y, panel.width, panel.height, 12, 12);
		graphics.setComposite(old);
	}

	private void playSounds(ReelAnimation reel, double position, ReelAnimation.Phase phase, long now)
	{
		if (reel != soundAnimation)
		{
			soundAnimation = reel;
			lastTile = (long) Math.floor(position);
			stopSoundPlayed = false;
		}
		if (!config.soundEffects())
		{
			return;
		}

		long tile = (long) Math.floor(position);
		if (phase == ReelAnimation.Phase.REVEAL)
		{
			if (!stopSoundPlayed)
			{
				stopSoundPlayed = true;
				client.playSoundEffect(reel.winner().getTier() == Tier.LEGENDARY
					? SoundEffectID.GE_COIN_TINKLE
					: SoundEffectID.GE_ADD_OFFER_DINGALING);
			}
		}
		else if (tile != lastTile && now - lastTickSoundNanos >= TICK_SOUND_GAP_NANOS)
		{
			lastTile = tile;
			lastTickSoundNanos = now;
			client.playSoundEffect(SoundEffectID.UI_BOOP);
		}
	}

	/**
	 * Draws text with a shadow, falling back to a system font if the game font
	 * lacks one of its characters.
	 */
	static void drawCentered(Graphics2D graphics, String text, int centreX, int baseline, Color color)
	{
		Font font = FontManager.getRunescapeBoldFont();
		if (font.canDisplayUpTo(text) != -1)
		{
			font = new Font(Font.SANS_SERIF, Font.BOLD, 13);
		}
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();
		int x = centreX - metrics.stringWidth(text) / 2;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, baseline + 1);
		graphics.setColor(color);
		graphics.drawString(text, x, baseline);
	}
}

