		assertEquals(ReelAnimation.Phase.SETTLING, reel.phase(at(1)));
		assertTrue(reel.coverVisible(at(1)));
		double end = settleEnd(reel);
		assertEquals(ReelAnimation.Phase.REVEAL, reel.phase(at(end)));
