package com.lockboxcaseopening;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import java.util.Random;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class UnboxControllerTest
{
	private static final long SECOND = 1_000_000_000L;
	private static final int BOX = DropTable.LOCKBOX_ID;
	private static final Loot DARTS = new Loot(ItemID.DRAGON_DART, 125, Tier.COMMON);

	private final UnboxController controller = new UnboxController(new Random(1));

	private static Map<Integer, Integer> inv(int... pairs)
	{
		Map<Integer, Integer> map = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			map.put(pairs[i], pairs[i + 1]);
		}
		return map;
	}

	private void open(long nanos)
	{
		controller.openClicked(inv(BOX, 1, ItemID.SHARK, 3), nanos, 6, 4);
	}

	private void receiveDarts(long nanos)
	{
		controller.inventoryChanged(inv(ItemID.SHARK, 3, ItemID.DRAGON_DART, 125), nanos);
	}

	@Test
	public void openStartsSpinningWithoutAWinner()
	{
		open(0);
		assertTrue(controller.isActive());
		assertFalse(controller.animation().hasWinner());
		assertEquals(ReelAnimation.Phase.SPINNING, controller.animation().phase(SECOND));
	}

	@Test
	public void consumedBoxSetsTheWinner()
	{
		open(0);
		receiveDarts(SECOND / 2);
		assertEquals(DARTS, controller.animation().winner());
	}

	@Test
	public void otherInventoryChangeKeepsWaiting()
	{
		open(0);
		controller.inventoryChanged(inv(BOX, 1, ItemID.SHARK, 2), SECOND / 2);
		assertTrue(controller.isActive());
		assertFalse(controller.animation().hasWinner());
	}

	@Test
	public void noBoxConsumedTimesOut()
	{
		open(0);
		for (int i = 0; i < UnboxController.TIMEOUT_TICKS - 1; i++)
		{
			controller.gameTick();
		}
		assertTrue(controller.isActive());
		controller.gameTick();
		assertFalse(controller.isActive());
	}

	@Test
	public void consumedBoxStopsTheTimeout()
	{
		open(0);
		receiveDarts(SECOND / 2);
		for (int i = 0; i < UnboxController.TIMEOUT_TICKS * 2; i++)
		{
			controller.gameTick();
		}
		assertTrue(controller.isActive());
	}

	@Test
	public void consumedWithNoGainCloses()
	{
		open(0);
		controller.inventoryChanged(inv(ItemID.SHARK, 3), SECOND / 2);
		assertFalse(controller.isActive());
	}

	@Test
	public void secondOpenDuringSpinIsIgnored()
	{
		open(0);
		ReelAnimation first = controller.animation();
		open(SECOND);
		assertSame(first, controller.animation());
	}

	@Test
	public void openDuringRevealStartsNew()
	{
		open(0);
		receiveDarts(0);
		ReelAnimation first = controller.animation();
		long inReveal = 7 * SECOND;
		assertEquals(ReelAnimation.Phase.REVEAL, first.phase(inReveal));
		open(inReveal);
		assertNotSame(first, controller.animation());
		assertEquals(ReelAnimation.Phase.SPINNING, controller.animation().phase(inReveal));
	}

	@Test
	public void staleCloseDoesNotKillNewAnimation()
	{
		open(0);
		ReelAnimation stale = controller.animation();
		controller.close();
		open(SECOND);
		controller.close(stale);
		assertTrue(controller.isActive());
	}

	@Test
	public void closeWithCurrentAnimationCloses()
	{
		open(0);
		controller.close(controller.animation());
		assertFalse(controller.isActive());
		assertNull(controller.animation());
	}

	@Test
	public void updateClosesWhenDone()
	{
		open(0);
		receiveDarts(0);
		controller.update(7 * SECOND);
		assertTrue(controller.isActive());
		controller.update(11 * SECOND);
		assertFalse(controller.isActive());
	}

	@Test
	public void closeWorksInEveryPhase()
	{
		open(0);
		controller.close();
		assertFalse(controller.isActive());

		open(0);
		receiveDarts(0);
		assertEquals(ReelAnimation.Phase.SETTLING, controller.animation().phase(SECOND));
		controller.close();
		assertFalse(controller.isActive());

		open(0);
		controller.inventoryChanged(inv(ItemID.SHARK, 3, ItemID.OATHPLATE_HELM, 1), 0);
		assertEquals(ReelAnimation.Phase.REVEAL, controller.animation().phase(60 * SECOND));
		controller.close();
		assertFalse(controller.isActive());
	}

	@Test
	public void gainBeforeTheBoxIsConsumedIsNotCountedAsLoot()
	{
		controller.openClicked(inv(BOX, 1), 0, 6, 4);
		controller.inventoryChanged(inv(BOX, 1, ItemID.COINS, 1000), SECOND / 4);
		controller.inventoryChanged(inv(ItemID.COINS, 234333), SECOND / 2);
		assertEquals(new Loot(ItemID.COINS, 233333, Tier.VERY_RARE), controller.animation().winner());
	}

	@Test
	public void twoBoxesConsumedAtOnceCloseWithoutAResult()
	{
		controller.openClicked(inv(BOX, 3), 0, 6, 4);
		controller.inventoryChanged(inv(BOX, 1, ItemID.DRAGON_DART, 125, ItemID.OATHPLATE_HELM, 1), SECOND / 2);
		assertFalse(controller.isActive());
	}

	@Test
	public void realOpenShowsTheCoverUntilTheReelStops()
	{
		open(0);
		assertTrue(controller.coverVisible(SECOND));
		receiveDarts(0);
		assertFalse(controller.coverVisible(7 * SECOND));
	}

	@Test
	public void idleHasNoCover()
	{
		assertFalse(controller.coverVisible(SECOND));
	}
}

package com.lockboxcaseopening;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.inject.Guice;
import java.awt.Component;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.Random;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import org.junit.Test;

public class UnboxMouseListenerTest
{
	private static final Rectangle PANEL = new Rectangle(100, 100, 200, 100);
	private static final Rectangle COVER = new Rectangle(500, 300, 100, 200);
	private static final Point INSIDE = new Point(150, 150);
	private static final Point OVER_COVER = new Point(550, 400);
	private static final Point OUTSIDE = new Point(10, 10);

	private static MouseEvent event(int id, Point point)
	{
		Component source = new Component()
		{
		};
		return new MouseEvent(source, id, 0, 0, point.x, point.y, 1, false, MouseEvent.BUTTON1);
	}

	private static MouseManager newMouseManager()
	{
		RuneLiteConfig config = new RuneLiteConfig()
		{
		};
		return Guice.createInjector(binder -> binder.bind(RuneLiteConfig.class).toInstance(config))
			.getInstance(MouseManager.class);
	}

	private final UnboxController controller = new UnboxController(new Random(1));
	private final UnboxMouseListener listener =
		new UnboxMouseListener(controller, () -> PANEL, () -> COVER, Runnable::run);

	@Test
	public void insideDuringSpinConsumes()
	{
		assertEquals(ClickAction.CONSUME,
			UnboxMouseListener.decide(INSIDE, PANEL, COVER, ReelAnimation.Phase.SPINNING));
	}

	@Test
	public void insideDuringRevealClosesAndConsumes()
	{
		assertEquals(ClickAction.CLOSE_AND_CONSUME,
			UnboxMouseListener.decide(INSIDE, PANEL, null, ReelAnimation.Phase.REVEAL));
	}

	@Test
	public void outsideClosesAndPasses()
	{
		assertEquals(ClickAction.CLOSE_AND_PASS,
			UnboxMouseListener.decide(OUTSIDE, PANEL, COVER, ReelAnimation.Phase.SETTLING));
	}

	@Test
	public void overCoverClosesAndConsumes()
	{
		assertEquals(ClickAction.CLOSE_AND_CONSUME,
			UnboxMouseListener.decide(OVER_COVER, PANEL, COVER, ReelAnimation.Phase.SPINNING));
	}

	@Test
	public void noCoverDuringReveal()
	{
		assertEquals(ClickAction.CLOSE_AND_PASS,
			UnboxMouseListener.decide(OVER_COVER, PANEL, null, ReelAnimation.Phase.REVEAL));
	}

	@Test
	public void outsidePressClosesTheAnimation()
	{
		controller.openClicked(Collections.emptyMap(), System.nanoTime(), 6, 4);
		MouseEvent press = event(MouseEvent.MOUSE_PRESSED, OUTSIDE);
		listener.mousePressed(press);
		assertNull(controller.animation());
		assertFalse(press.isConsumed());
	}

	@Test
	public void releaseOfConsumedPressIsConsumed()
	{
		controller.openClicked(Collections.emptyMap(), System.nanoTime(), 6, 4);

		MouseEvent press = event(MouseEvent.MOUSE_PRESSED, OVER_COVER);
		listener.mousePressed(press);
		assertTrue(press.isConsumed());
		assertTrue(listener.awaitingRelease());

		MouseEvent release = event(MouseEvent.MOUSE_RELEASED, OVER_COVER);
		listener.mouseReleased(release);
		assertTrue(release.isConsumed());
		assertFalse(listener.awaitingRelease());

		MouseEvent click = event(MouseEvent.MOUSE_CLICKED, OVER_COVER);
		listener.mouseClicked(click);
		assertTrue(click.isConsumed());
	}

	@Test
	public void clicksPassThroughWhenIdle()
	{
		MouseEvent press = event(MouseEvent.MOUSE_PRESSED, INSIDE);
		listener.mousePressed(press);
		assertFalse(press.isConsumed());
	}

	@Test
	public void runsAfterStretchedModeHasTranslatedTheClick()
	{
		Point stretched = new Point(1300, 700);
		Point real = new Point(650, 350);
		MouseManager mouseManager = newMouseManager();
		mouseManager.registerMouseListener(0, new MouseAdapter()
		{
			@Override
			public MouseEvent mousePressed(MouseEvent event)
			{
				return event(MouseEvent.MOUSE_PRESSED, real);
			}
		});
		Rectangle coverAtRealPosition = new Rectangle(600, 300, 100, 100);
		UnboxMouseListener stretchedListener =
			new UnboxMouseListener(controller, () -> PANEL, () -> coverAtRealPosition, Runnable::run);
		controller.openClicked(Collections.emptyMap(), System.nanoTime(), 6, 4);

		UnboxMouseListener.register(mouseManager, stretchedListener);
		MouseEvent result = mouseManager.processMousePressed(event(MouseEvent.MOUSE_PRESSED, stretched));

		assertTrue(result.isConsumed());
	}
}

